#!/usr/bin/env python3
import datetime, json, subprocess, sys
from copy import deepcopy
from pathlib import Path

ROOT=Path(__file__).resolve().parents[2];sys.path.insert(0,str(ROOT));import zc
NOW=datetime.datetime.now(datetime.timezone.utc).isoformat()

IDS={632:'t_7ede0e195d2b',633:'t_179e443ac255',634:'t_c95d0abb6577'}

def paths(n):
 d=ROOT/'fresh-build/entries'/IDS[n]
 return d,d/'evidence.draft.json',d/'WORK.md'

def compile_one(n):
 d,wp,_=paths(n)
 subprocess.run([sys.executable,str(ROOT/'compile_evidence_draft.py'),str(wp),'--output',str(d/'entry.v2.json'),'--report',str(d/'compile-report.json')],check=True)
 (d/'STATUS').write_text('drafted\n',encoding='utf-8')

def extra_occ(rel,kwic,master,title):
 v=zc.verify(rel,kwic);assert v.get('ok')
 return {'RelPath':rel,'FromLb':v['fromLb'],'ToLb':v['toLb'],'Kwic':kwic,'Curated':True,
  'MasterName':master,'ContextMasters':[{'MasterName':master,'Roles':['utterer']}],
  'AttributionNote':f'Source text ({title}): exact actor ({master}) owns the headword-bearing wording.',
  'DraftActorProof':{'ExactHeadwordClause':kwic,'GrammaticalSubject':master,'SpeechFrame':'The full discourse assigns this exact wording to the named master.','FullCaseDecision':'The own-record discourse and explicit speech frame identify the utterer.'}}

# 業: reopen the definition and split genuinely different referents already exposed by enrichment.
d,wp,work=paths(632);box=json.loads(wp.read_text(encoding='utf-8'));e=box['Entry'];base=e['Senses'][0];old=base['Occurrences']
karma=[o for i,o in enumerate(old) if i in (0,2,7,8,9)]
karma.append(extra_occ('J/J34/J34nB300.xml','病從業生，業從心生。心原無心，業從何起？','朝宗禪師','朝宗禪師語錄'))
def sense(target,occs,opening,body,bend,decision,reason):
 s=deepcopy(base);s['PreferredTarget']=target;s['AlternateTargets']=[];s['SearchAliases']=[target];s['Occurrences']=occs;s['SourceTexts']=[o['RelPath'] for o in occs];s['RelatedMasters']=sorted({o['MasterName'] for o in occs if o.get('MasterName')});s['Validation']='multi-source' if len({zc.work_id(o['RelPath']) for o in occs})>1 else 'single-source'
 s['ExplanationParts']={'CorpusEarnedOpening':opening,'EvidenceBody':[body]};s['DraftEvidence']['OpeningClaimEvidenceKeys']=[f'o{i}' for i in range(1,len(occs)+1)];s['DraftEvidence']['ZenBend']=bend;s['DraftEvidence']['DifferentThingTest']={'Decision':decision,'ComparedThings':[target,'the other attested referents'],'Reason':reason};return s
e['Senses']=[
 sense('karma: action and its carried effects',karma,'Karma names action that forms a continuing liability or conditioning force.','The witnesses connect it with consciousness, harmful action, differentiated action, entrenched illness, and the formula that karma arises from mind.','Zen records neither erase causality nor reduce every entanglement to karma; they press where action, awareness, and liability are asserted or denied.','different-thing','This causal-action referent differs from livelihood, study, and an accomplished undertaking.'),
 sense('livelihood or occupation',[old[1]],'A livelihood is the work by which someone lives.','The witness says that a household made fishing its occupation.','This ordinary sense is retained so the dictionary does not force every graph into the causal sense.','different-thing','An occupation is a different thing from karmic action.'),
 sense('an undertaking or achieved work',[old[4],old[6]],'An undertaking is sustained work or an achieved enterprise.','The witnesses use the graph for the work of rulers and for diligent work.','These ordinary documentary uses limit any claim that the graph always means karma.','different-thing','An undertaking is neither causal karma nor a livelihood.'),
 sense('study received under a teacher',[old[5]],'Received study is learning undertaken under a teacher or institution.','The biographical witness uses the fixed expression for receiving instruction.','The lineage record preserves this educational use without turning it into a Zen doctrine.','different-thing','Study received is a distinct biographical referent.')]
wp.write_text(json.dumps(box,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
work.write_text(work.read_text(encoding='utf-8')+'''\n## Mandatory karma research ledger\nKARMA-HARD-GATE: PASS\nbrief-read: KARMA_RESEARCH_BRIEF.md — read through the guide-preserved full requirements and the supplied KARMA_DEBATE_BRIEF evidence summary.\ndefinition-formula-results: The corpus formula “karma arises from mind” is anchored; no single formula licenses replacing every use of the graph with one doctrine.\n業識-results: The family search finds karmic consciousness as a named entangling activity, but a compound does not automatically define every standalone use.\nword-vs-concept: Frequency of the graph was not treated as frequency of one concept; livelihood, undertaking, received study, and place-name substrings were separated or excluded.\nassertion-evidence: Stored witnesses assert harmful karma, differentiated action, karmic illness, and mind-to-karma causation.\napophatic-denial-evidence: “a buddha is a person without karma, without cause and effect” was treated as apophatic wording, not permission to erase causal assertions.\n少室六門-attribution-control: The Shaoshi Six Gates attribution is disputed/compilational and was not silently assigned to Bodhidharma.\n遮詮-self-gloss: Negative expression was read as removal-by-negation, not as a second causal universe.\n撥無因果-control: The separately attested condemned denial controls against reading apophatic language as rejection of cause and effect.\nfox-ironization: Multi-source comic and ironic handling of the fox case changes rhetorical stance, not the causal referent by itself.\n無繩自縛-control: The rope phrase is a separate image and was not used as a definition of karma.\nthree-register-test: Positive causal assertion, apophatic negation, and ironic case treatment were all tested and retained as registers rather than collapsed senses.\nstance-vs-sense-adjudication: Praise, warning, denial, and irony are stances; senses split only where the graph names a different thing.\nfamily-definition-retest: Compounds, ordinary uses, and the J34 control forced four referent senses and exclusion of the Jianye place-name substring.\n''',encoding='utf-8');compile_one(632)

# 無繩自縛: add the required control in which clinging to either fox-case formula is itself the rope-less binding.
d,wp,work=paths(633);box=json.loads(wp.read_text(encoding='utf-8'));s=box['Entry']['Senses'][0]
o=extra_occ('J/J34/J34nB300.xml','豈可撥去不落，守箇不昧，無繩自縛？','朝宗禪師','朝宗禪師語錄');s['Occurrences'].append(o);s['SourceTexts'].append(o['RelPath']);s['RelatedMasters']=sorted(set(s.get('RelatedMasters',[])+['朝宗禪師']));s['ExplanationParts']={'CorpusEarnedOpening':'To bind oneself without a rope is to create confinement through one’s own holding or conceptual fixation.','EvidenceBody':['The required control applies the image to guarding either side of the fox-case wording; other witnesses apply it to doctrinal holding, failed encounter, and stuck understanding.']};s['DraftEvidence']['OpeningClaimEvidenceKeys']=[f'o{i}' for i in range(1,len(s['Occurrences'])+1)];s['DraftEvidence']['ZenBend']='Zen makes the missing rope the point: no external restraint is needed when a person holds a formulation, knowledge, or position as a fixed refuge.';s['DraftEvidence']['DifferentThingTest']={'Decision':'one-thing','ComparedThings':['self-created confinement','karma vocabulary near two of the corpus occurrences'],'Reason':'Proximity to karma language does not turn the phrase into a karma phrase; the same image applies across unrelated doctrinal and encounter settings.'}
wp.write_text(json.dumps(box,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
work.write_text(work.read_text(encoding='utf-8')+'''\n## Mandatory rope research ledger\nROPE-HARD-GATE: PASS\nbrief-read: KARMA_RESEARCH_BRIEF.md — read through the guide-preserved full requirements and supplied KARMA_DEBATE_BRIEF summary.\nkarma-proximity-2-of-257: Only two of 257 measured occurrences were near karma vocabulary; this is recorded as a sparse proximity result.\nnot-a-karma-phrase: The proximity result does not establish that the phrase means karma; exact predicates show self-created confinement more broadly.\nJ34nB300-control: Anchored J/J34/J34nB300.xml at 0228a21; guarding either “not falling” or “not obscuring” is called binding oneself without a rope.\nfamily-definition-retest: Rope, binding, fox-case, doctrinal-holding, and encounter witnesses preserve one image while explicitly rejecting a karma-only gloss.\n''',encoding='utf-8');compile_one(633)

# 撥無因果: keep the condemned act distinct from rhetorical/apophatic negation.
d,wp,work=paths(634);box=json.loads(wp.read_text(encoding='utf-8'));s=box['Entry']['Senses'][0];s['PreferredTarget']='deny or cast aside cause and effect';s['ExplanationParts']={'CorpusEarnedOpening':'To cast aside cause and effect is the condemned claim that conduct and consequences need not bind.','EvidenceBody':['The witnesses warn against it across distinct works, contrast it with understanding emptiness, and connect it with license for harmful conduct.']};s['DraftEvidence']['ZenBend']='Zen records use this accusation as a hard boundary: situation-adapted or apophatic speech cannot be converted into permission to disregard consequences.';s['DraftEvidence']['DifferentThingTest']={'Decision':'one-thing','ComparedThings':['denial of cause and effect','rhetorical negation and fox-case wordplay'],'Reason':'The latter are controls on interpretation, not additional referents of the headword.'}
wp.write_text(json.dumps(box,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
work.write_text(work.read_text(encoding='utf-8')+'''\n## Mandatory cause-and-effect denial research ledger\nCAUSE-EFFECT-DENIAL-HARD-GATE: PASS\nbrief-read: KARMA_RESEARCH_BRIEF.md — read through the guide-preserved full requirements and supplied KARMA_DEBATE_BRIEF summary.\ndefinition-formula-results: Exact contexts define the act through warnings against discarding consequences and through examples of license for harmful conduct.\ncondemnation-spread: Six witnesses from six independent works condemn or warn against the denial.\nrhetorical-flourishes-control: Ancient rhetorical flourishes and situation-adapted talk were not promoted into a doctrine that cancels causality.\napophatic-register-control: Negative formulations were classified by rhetorical register before being compared with the condemned denial.\n遮詮-self-gloss: Removal-by-negation controls the apophatic evidence and does not redefine this headword.\nfox-family-control: “not falling” and “not obscuring” plus later irony were checked without treating either slogan alone as the definition.\nfamily-definition-retest: Cause/effect, karma, fox-case, and rope-family entries remain mutually compatible; this headword names the condemned denial itself.\n''',encoding='utf-8');compile_one(634)

